<script setup>
import { ref, computed, nextTick, onMounted, onBeforeUnmount } from 'vue'
import FlowIcon from './components/FlowIcon.vue'
import { useWallet } from './composables/useWallet'
import { CLUSTER_LABEL, SOCIAL_URL, TOKEN_EXPLORER_URL, TOKEN_MINT, TOKEN_SYMBOL } from './config'
const { connected, account, shortAccount, balance, tokenBalance, walletCluster, correctNetwork, isConnecting, isRefreshing, walletError, tokenError, tokenNotice, tokenConfigured, connectWallet, disconnect, refreshBalances } = useWallet()
const pages=['Overview','Pools','Positions','Governance']; const navLabels={Overview:'Desk',Pools:'Routes',Positions:'Positions',Governance:'Governance'}; const navIcons={Overview:'grid',Pools:'layers',Positions:'portfolio',Governance:'community'}
const activePage=ref('Overview'), search=ref(''), filter=ref('All pools'), sort=ref('featured')
const pools=[{id:'orl-sol',name:'ORL / SOL',pair:'ORL / SOL',token:'ORL',profile:'Core',apr:18.4,tvl:2.84,volume:184.2,fee:'0.30%',color:'green',symbols:['O','S'],model:'Balanced liquidity'},{id:'sol-usdc',name:'SOL / USDC',pair:'SOL / USDC',token:'SOL',profile:'Stable',apr:9.8,tvl:14.2,volume:902.6,fee:'0.05%',color:'purple',symbols:['S','$'],model:'Stable pair liquidity'},{id:'orl-usdc',name:'ORL / USDC',pair:'ORL / USDC',token:'ORL',profile:'Experimental',apr:31.6,tvl:.92,volume:74.8,fee:'1.00%',color:'orange',symbols:['O','$'],model:'Variable liquidity'}]
const filteredPools=computed(()=>{const q=search.value.trim().toLowerCase(); const rows=pools.filter(p=>(filter.value==='All pools'||p.profile===filter.value)&&`${p.name} ${p.pair} ${p.profile}`.toLowerCase().includes(q)); if(sort.value==='apr')rows.sort((a,b)=>b.apr-a.apr); if(sort.value==='tvl')rows.sort((a,b)=>b.tvl-a.tvl); return rows})
const selectedPoolId=ref(pools[0].id), selectedPool=computed(()=>pools.find(p=>p.id===selectedPoolId.value)||pools[0]), secondaryToken=computed(()=>selectedPool.value.pair.split(' / ')[1]), allocation=ref(50), allocationLabel=computed(()=>`${allocation.value}% ${selectedPool.value.token}, ${100-allocation.value}% ${secondaryToken.value}`)
const positions=ref([]), storageKey='solana.preview-positions.v1', modal=ref(''), previewStep=ref(1), previewAmount=ref(''), reviewedAmount=ref(''), amountError=ref(''), acknowledged=ref(false), dialog=ref(null), previewInput=ref(null), toast=ref(''); let previousFocus=null,toastTimer
const walletStatusDescription=computed(()=>{if(!connected.value)return 'Local previews work without a wallet.'; if(correctNetwork.value===false)return `Wallet reports Solana ${walletCluster.value}; reads are paused because this app uses ${CLUSTER_LABEL}.`; const c=walletCluster.value==='unknown'?'an unverified wallet cluster':`Solana ${walletCluster.value}`; return `Wallet reports ${c}; native SOL is read from ${CLUSTER_LABEL}.`})
function notify(m){clearTimeout(toastTimer);toast.value=m;toastTimer=setTimeout(()=>toast.value='',4200)}
function readRoute(){const hash=window.location.hash.slice(1).toLowerCase();activePage.value=hash==='staking'?'Positions':pages.find(p=>p.toLowerCase()===hash)||'Overview';document.title=`${navLabels[activePage.value]} | Poolumi`}
function goTo(page){closeModal();activePage.value=page;window.location.hash=page.toLowerCase();window.scrollTo({top:0,behavior:'instant'});nextTick(()=>document.getElementById('main-content')?.focus({preventScroll:true}))}
function openModal(type){if(modal.value)return;previousFocus=document.activeElement;modal.value=type;document.body.style.overflow='hidden';nextTick(()=>{dialog.value?.showModal();if(type==='pool')previewInput.value?.focus()})}
function closeModal(){if(dialog.value?.open)dialog.value.close();else modal.value=''} function onDialogClose(){document.body.style.overflow='';modal.value='';if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true})}
function onBackdrop(e){if(e.target!==dialog.value)return;const r=dialog.value.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}
function openPool(pool){selectedPoolId.value=pool.id;previewStep.value=1;previewAmount.value='';reviewedAmount.value='';amountError.value='';acknowledged.value=false;openModal('pool')}
function selectPool(pool){selectedPoolId.value=pool.id;allocation.value=pool.id==='sol-usdc'?70:pool.id==='orl-usdc'?35:50}
function validAmount(v){return typeof v==='string'&&/^(?:\d+(?:\.\d{1,6})?|\.\d{1,6})$/.test(v.trim())&&Number(v)>0&&Number(v)<=1000000}
function reviewPreview(){if(!validAmount(previewAmount.value)){amountError.value='Enter an amount above 0 with up to 6 decimal places.';previewInput.value?.focus();return}amountError.value='';reviewedAmount.value=String(Number(previewAmount.value));previewStep.value=2}
function loadPositions(){try{const saved=JSON.parse(sessionStorage.getItem(storageKey)||'[]');if(Array.isArray(saved))positions.value=saved.filter(p=>p&&pools.some(pool=>pool.id===p.poolId)&&validAmount(String(p.amount))).slice(0,100)}catch{positions.value=[];notify('Saved previews could not be read; starting a new session.')}}
function persistPositions(){try{sessionStorage.setItem(storageKey,JSON.stringify(positions.value));return true}catch{notify('This browser blocked session storage. The preview is visible only until refresh.');return false}}
function savePreview(){if(!acknowledged.value||!validAmount(reviewedAmount.value))return;positions.value.unshift({id:crypto.randomUUID?.()||`preview-${Date.now()}`,poolId:selectedPool.value.id,amount:reviewedAmount.value,allocation:allocation.value,createdAt:Date.now()});persistPositions();goTo('Positions');notify('Preview saved locally. No assets moved and no transaction was sent.')}
function removePosition(p){positions.value=positions.value.filter(x=>x.id!==p.id);persistPositions();notify('Preview removed from this session.')}; function poolFor(p){return pools.find(x=>x.id===p.poolId)||pools[0]}; function displayDate(v){return new Date(v).toLocaleDateString('en-US',{month:'short',day:'numeric'})}; function displayAmount(v){return Number(v).toLocaleString('en-US',{maximumFractionDigits:6})}; function resetFilters(){filter.value='All pools';search.value='';sort.value='featured'}
async function connect(){if(await connectWallet())notify('Solana wallet connected.')}; async function copyAddress(){if(!account.value)return;try{await navigator.clipboard.writeText(account.value);notify('Wallet address copied.')}catch{notify('Copy failed. Select the address and copy it manually.')}}
onMounted(()=>{readRoute();loadPositions();window.addEventListener('hashchange',readRoute)});onBeforeUnmount(()=>{window.removeEventListener('hashchange',readRoute);clearTimeout(toastTimer)})
</script>

<template>
<div class="app-shell"><a class="skip-link" href="#main-content" @click.prevent="document.getElementById('main-content')?.focus()">Skip to content</a><div class="app-frame">
<aside class="sidebar"><a class="brand-lockup" href="#overview" @click.prevent="goTo('Overview')" aria-label="Poolumi desk home"><img src="/poolumi-mark.svg" alt="" width="32" height="32"><span>poolumi<span class="brand-dot">.</span></span></a><div class="sidebar-network"><i class="status-dot"></i><span>{{ CLUSTER_LABEL }}</span><span class="network-caret">⌄</span></div><nav class="sidebar-nav" aria-label="Main navigation"><span class="nav-caption">WORKSPACE</span><a v-for="page in pages" :key="page" :href="'#'+page.toLowerCase()" :class="{active:activePage===page}" :aria-current="activePage===page?'page':undefined" @click.prevent="goTo(page)"><FlowIcon :name="navIcons[page]"/><span>{{ navLabels[page] }}</span><b v-if="page==='Positions'&&positions.length" class="nav-count">{{ positions.length }}</b></a></nav><div class="sidebar-bottom"><button class="wallet-chip" @click="openModal('wallet')"><span class="wallet-avatar"><FlowIcon name="wallet"/></span><span><strong>{{ connected?shortAccount:'Connect wallet' }}</strong><small>{{ connected?'Balance reader':'Optional' }}</small></span><FlowIcon name="chevron"/></button><div class="sidebar-meta"><span>POOLUMI</span><span>Read the pool. Pick your route.</span></div></div></aside>
<main id="main-content" tabindex="-1" class="main-content"><header class="topbar"><div><span class="topbar-kicker">{{ navLabels[activePage] }} / {{ CLUSTER_LABEL }}</span><h1>{{ activePage==='Overview'?'Liquidity desk':navLabels[activePage] }}</h1></div><div class="topbar-actions"><span class="fixture-note"><i class="status-dot"></i> Demo fixtures</span><button class="icon-button" aria-label="Open guide" @click="openModal('docs')"><FlowIcon name="book"/></button><button class="button button-wallet top-wallet" @click="openModal('wallet')"><FlowIcon name="wallet"/><span>{{ connected?shortAccount:'Connect' }}</span></button></div></header>
<section v-if="activePage==='Overview'" class="desk-page"><div class="metric-strip"><div><span>ROUTES TRACKED</span><strong>{{ pools.length }}</strong><small>demo pairs</small></div><div><span>COMBINED TVL</span><strong>$18.0M</strong><small>fixture total</small></div><div><span>24H VOLUME</span><strong>$1.16B</strong><small>fixture total</small></div><div class="metric-positive"><span>TOP APR</span><strong>31.6%</strong><small>ORL / USDC</small></div></div><div class="workbench-grid"><section class="route-board panel"><div class="panel-header"><div><span class="eyebrow">ROUTE BOARD</span><h2>Choose a pool route</h2></div><button class="text-button" @click="goTo('Pools')">View all <FlowIcon name="arrow"/></button></div><div class="route-toolbar"><div class="route-tabs"><button v-for="option in ['All pools','Core','Stable','Experimental']" :key="option" :class="{selected:filter===option}" @click="filter=option">{{ option }}</button></div><label class="search-field"><FlowIcon name="search"/><input v-model="search" type="search" placeholder="Search pair" aria-label="Search pool routes"></label></div><div class="route-list"><button v-for="pool in filteredPools" :key="pool.id" class="route-row" :class="{selected:selectedPool.id===pool.id}" @click="selectPool(pool)"><span :class="['route-pair-icon',pool.color]"><span>{{ pool.symbols[0] }}</span><span>{{ pool.symbols[1] }}</span></span><span class="route-name"><strong>{{ pool.name }}</strong><small>{{ pool.profile }} · {{ pool.fee }} fee</small></span><span class="route-stat"><small>APR</small><strong>{{ pool.apr }}%</strong></span><span class="route-stat"><small>TVL</small><strong>${{ pool.tvl }}M</strong></span><span class="route-stat route-volume"><small>24H VOL</small><strong>${{ pool.volume }}M</strong></span><FlowIcon name="chevron"/></button><div v-if="!filteredPools.length" class="compact-empty">No matching routes. <button class="text-button" @click="resetFilters">Reset</button></div></div><div class="route-detail"><div class="detail-heading"><div><span class="eyebrow">SELECTED ROUTE</span><h3>{{ selectedPool.name }}</h3></div><span class="tag tag-green">{{ selectedPool.profile }}</span></div><div class="route-chart"><div v-for="n in 28" :key="n" class="chart-bar" :style="{height:(24+((n*19+selectedPool.apr*4)%68))+'%'}"></div><span class="chart-badge">{{ selectedPool.apr }}% APR</span></div><div class="detail-stats"><div><span>Pool model</span><strong>{{ selectedPool.model }}</strong></div><div><span>Fee tier</span><strong>{{ selectedPool.fee }}</strong></div><div><span>Updated</span><strong>Fixture set A</strong></div></div></div></section>
<aside class="composer panel" aria-label="Position composer"><div class="panel-header"><div><span class="eyebrow">POSITION COMPOSER</span><h2>Build a preview</h2></div><span class="tag">LOCAL</span></div><div class="composer-route"><span :class="['route-pair-icon large',selectedPool.color]"><span>{{ selectedPool.symbols[0] }}</span><span>{{ selectedPool.symbols[1] }}</span></span><div><strong>{{ selectedPool.name }}</strong><small>{{ selectedPool.model }}</small></div><button class="icon-button" aria-label="Change selected route" @click="goTo('Pools')"><FlowIcon name="chevron"/></button></div><div class="allocation-block"><div class="allocation-head"><span>Allocation split</span><b>{{ allocationLabel }}</b></div><div class="allocation-ring" :style="{'--mix':allocation+'%'}"><strong>{{ allocation }}%</strong><small>{{ selectedPool.token }}</small></div><input v-model.number="allocation" aria-label="Allocation split" type="range" min="10" max="90" step="5"><div class="allocation-legend"><span><i class="legend-dot green"></i>{{ selectedPool.token }} <b>{{ allocation }}%</b></span><span><i class="legend-dot violet"></i>{{ secondaryToken }} <b>{{ 100-allocation }}%</b></span></div></div><div class="composer-quote"><div><span>Demo APR</span><strong>{{ selectedPool.apr }}%</strong></div><div><span>Demo TVL</span><strong>${{ selectedPool.tvl }}M</strong></div><div><span>Fee</span><strong>{{ selectedPool.fee }}</strong></div></div><button class="button button-primary full-width composer-action" @click="openPool(selectedPool)">Enter amount <FlowIcon name="arrow"/></button><p class="composer-note"><FlowIcon name="shield"/> Practice only. No signature or deposit.</p></aside></div><section class="desk-footnote"><FlowIcon name="info"/><span>Fictional demo metrics are interface fixtures for product testing. Connect a wallet only when you want to read SOL and {{ TOKEN_SYMBOL }} balances from {{ CLUSTER_LABEL }}.</span><button class="text-button" @click="openModal('wallet')">Wallet settings <FlowIcon name="arrow"/></button></section></section>
<section v-else-if="activePage==='Pools'" class="page-section"><div class="page-intro"><div><span class="eyebrow">ROUTE DISCOVERY</span><h2>Pool routes</h2><p>Compare fixture metrics, then open a local preview.</p></div><span class="tag tag-purple">{{ filteredPools.length }} ROUTES</span></div><div class="filter-bar"><div class="route-tabs"><button v-for="option in ['All pools','Core','Stable','Experimental']" :key="option" :class="{selected:filter===option}" @click="filter=option">{{ option }}</button></div><label class="search-field"><FlowIcon name="search"/><input v-model="search" type="search" placeholder="Search pools" aria-label="Search pools"></label><select v-model="sort" aria-label="Sort pools"><option value="featured">Featured</option><option value="apr">Demo APR</option><option value="tvl">Demo TVL</option></select></div><div class="pool-grid"><article v-for="pool in filteredPools" :key="pool.id" :class="['pool-card',pool.color,{selected:selectedPool.id===pool.id}]" @click="selectPool(pool)"><div class="pool-card-head"><span :class="['route-pair-icon',pool.color]"><span>{{ pool.symbols[0] }}</span><span>{{ pool.symbols[1] }}</span></span><span class="tag">{{ pool.profile }}</span></div><h3>{{ pool.name }}</h3><p>{{ pool.model }} · {{ pool.fee }} fee</p><div class="mini-chart"><i v-for="n in 18" :key="n" :style="{height:(25+((n*17+pool.apr*3)%65))+'%'}"></i></div><div class="pool-metrics"><div><span>Demo APR</span><strong>{{ pool.apr }}%</strong></div><div><span>Demo TVL</span><strong>${{ pool.tvl }}M</strong></div><div><span>24H VOL</span><strong>${{ pool.volume }}M</strong></div></div><button class="button button-secondary full-width" @click.stop="openPool(pool)">Preview route <FlowIcon name="arrow"/></button></article></div><div v-if="!filteredPools.length" class="empty-state"><FlowIcon name="search"/><h3>No routes found</h3><p>Try another pair or reset the filters.</p><button class="button button-secondary" @click="resetFilters">Reset filters</button></div></section>
<section v-else-if="activePage==='Positions'" class="page-section"><div class="page-intro"><div><span class="eyebrow">LOCAL LEDGER</span><h2>Saved positions</h2><p>Session previews stay in this browser tab.</p></div><button class="button button-primary" @click="goTo('Pools')"><FlowIcon name="plus"/> New preview</button></div><div class="position-summary"><span class="stat-icon purple"><FlowIcon name="portfolio"/></span><div><span>Saved previews</span><strong>{{ String(positions.length).padStart(2,'0') }}</strong></div><span class="tag">SESSION ONLY</span></div><div v-if="!positions.length" class="empty-state position-empty"><span class="empty-icon"><FlowIcon name="layers"/></span><h3>No saved previews yet</h3><p>Select a route, set an amount and save it for this session.</p><button class="button button-primary" @click="goTo('Pools')">Open route board <FlowIcon name="arrow"/></button></div><div v-else class="positions-ledger panel"><div class="ledger-head"><span>ROUTE / CREATED</span><span>AMOUNT</span><span>ALLOCATION</span><span>STATUS</span><span>ACTIONS</span></div><article v-for="position in positions" :key="position.id" class="position-entry"><div class="entry-identity"><span :class="['entry-icon',poolFor(position).color]">{{ poolFor(position).symbols[0] }}</span><div><h3>{{ poolFor(position).name }}</h3><p>{{ poolFor(position).profile }} / {{ displayDate(position.createdAt) }}</p></div></div><div class="position-amount">{{ displayAmount(position.amount) }}<span>{{ poolFor(position).token }}</span></div><div class="position-allocation">{{ position.allocation||50 }} / {{ 100-(position.allocation||50) }}</div><span class="position-status"><i class="status-dot"></i> Preview</span><button class="icon-button" :aria-label="'Remove '+poolFor(position).name+' preview'" @click="removePosition(position)"><FlowIcon name="trash"/></button></article></div><p class="session-note"><FlowIcon name="shield"/> Simulation only: no deposits, fees or accrued returns.</p></section>
<section v-else class="page-section"><div class="page-intro"><div><span class="eyebrow">PROTOCOL STATUS</span><h2>Governance</h2><p>Poolumi keeps the first release focused on research and local practice.</p></div><span class="tag tag-purple">COMING LATER</span></div><div class="governance-layout"><section class="governance-status-panel panel"><div class="governance-glyph"><FlowIcon name="community"/></div><span class="eyebrow">TOKEN + PROGRAM</span><h3>{{ tokenConfigured?'ORL mint configured.':'Mint pending.' }}<br>Governance paused.</h3><p>{{ tokenConfigured?'The ORL classic SPL Token mint is deployed on Solana Testnet. Pool and voting programs are not deployed.':'No Solana token mint, pool program, or voting account is configured in this workspace.' }}</p><div class="governance-status"><i class="status-dot"></i> {{ tokenConfigured?'ORL mint on '+CLUSTER_LABEL:'Waiting for deployment inputs' }}</div><p v-if="tokenConfigured" class="muted-note"><a :href="TOKEN_EXPLORER_URL" target="_blank" rel="noopener noreferrer">View ORL mint on Explorer <FlowIcon name="arrow"/></a></p></section><section class="roadmap-panel panel"><div class="panel-header"><div><span class="eyebrow">CAPABILITY MAP</span><h3>What works today</h3></div></div><ol class="roadmap-list"><li><span class="roadmap-node"><FlowIcon name="check"/></span><div><span class="tag tag-green">AVAILABLE</span><h4>Compare and simulate</h4><p>Browse fixture routes and save local previews without a wallet.</p><button class="text-button" @click="goTo('Pools')">Open route board <FlowIcon name="arrow"/></button></div></li><li><span class="roadmap-node"><FlowIcon name="check"/></span><div><span class="tag tag-blue">OPTIONAL</span><h4>Read a Solana wallet</h4><p>Connect an injected wallet to read native SOL and ORL balances from the configured RPC.</p><button class="text-button" @click="openModal('wallet')">Manage wallet <FlowIcon name="arrow"/></button></div></li><li class="future-step"><span class="roadmap-node"><FlowIcon name="clock"/></span><div><span class="tag">WAITING</span><h4>Pools, swaps, governance</h4><p>These actions stay disabled until their programs and governance accounts are deployed.</p></div></li></ol></section></div></section>
</main></div>
<nav class="mobile-tabs" aria-label="Mobile navigation"><a v-for="page in pages" :key="page" :href="'#'+page.toLowerCase()" :class="{active:activePage===page}" @click.prevent="goTo(page)"><FlowIcon :name="navIcons[page]"/><span>{{ navLabels[page] }}</span><b v-if="page==='Positions'&&positions.length">{{ positions.length }}</b></a></nav><footer class="site-footer"><span><b>poolumi</b> / Read the pool. Pick your route.</span><span>ORL mint configured on {{ CLUSTER_LABEL }} · Route metrics are fixtures.</span><div class="footer-links"><button @click="openModal('docs')">Guide <FlowIcon name="external"/></button><a v-if="SOCIAL_URL" :href="SOCIAL_URL" target="_blank" rel="noopener noreferrer">X <FlowIcon name="external"/></a></div></footer>
<dialog ref="dialog" class="app-dialog" :class="{'guide-dialog':modal==='docs'}" aria-labelledby="dialog-title" @click="onBackdrop" @close="onDialogClose"><div class="dialog-inner"><button class="dialog-close icon-button" aria-label="Close dialog" @click="closeModal"><FlowIcon name="close"/></button><template v-if="modal==='pool'"><div class="dialog-kicker"><span class="dialog-icon"><FlowIcon name="layers"/></span><span>LOCAL PREVIEW</span><span class="dialog-step">{{ previewStep }} / 2</span></div><h2 id="dialog-title">{{ previewStep===1?selectedPool.name:'Review route' }}</h2><p class="dialog-lead">{{ selectedPool.pair }} / {{ selectedPool.model }}</p><div class="dialog-notice"><FlowIcon name="shield"/><p>No assets move and no transaction is sent. Route metrics are interface fixtures.</p></div><form v-if="previewStep===1" @submit.prevent="reviewPreview"><label class="field-label" for="preview-amount">Practice amount</label><div class="amount-input"><input id="preview-amount" ref="previewInput" v-model="previewAmount" inputmode="decimal" placeholder="0.00" :aria-invalid="Boolean(amountError)"><span>{{ selectedPool.token }}</span></div><p v-if="amountError" class="form-error" role="alert">{{ amountError }}</p><div class="quick-amounts"><button v-for="amount in ['100','500','1000']" :key="amount" type="button" @click="previewAmount=amount">{{ amount }} {{ selectedPool.token }}</button></div><div class="review-lines"><div><span>Demo APR</span><b>{{ selectedPool.apr }}% / fixture</b></div><div><span>Network transaction</span><b>None</b></div></div><button class="button button-primary full-width" type="submit">Review preview <FlowIcon name="arrow"/></button></form><template v-else><div class="review-amount"><span>PRACTICE AMOUNT</span><strong>{{ displayAmount(reviewedAmount) }} <small>{{ selectedPool.token }}</small></strong></div><div class="review-lines"><div><span>Route</span><b>{{ selectedPool.name }}</b></div><div><span>Allocation</span><b>{{ allocationLabel }}</b></div><div><span>Saved to</span><b>This tab only</b></div></div><label class="check-label"><input v-model="acknowledged" type="checkbox"><span>I understand this is a simulation.</span></label><button class="button button-primary full-width" :disabled="!acknowledged" @click="savePreview">Save local preview <FlowIcon name="check"/></button><button class="text-button back-button" @click="previewStep=1">Back to amount</button></template></template><template v-else-if="modal==='wallet'"><div class="dialog-kicker"><span class="dialog-icon"><FlowIcon name="wallet"/></span><span>SOLANA WALLET</span></div><h2 id="dialog-title">Wallet balance reader</h2><p class="dialog-lead">Connect a Solana wallet to read native SOL and ORL balances from {{ CLUSTER_LABEL }}. The wallet's selected cluster is not switched.</p><div class="wallet-status-card"><FlowIcon name="wallet"/><div><strong>{{ connected?shortAccount:'No wallet connected' }}</strong><span>{{ walletStatusDescription }}</span></div><i v-if="connected" class="status-dot"></i></div><template v-if="connected"><button class="wallet-address" @click="copyAddress">{{ account }}</button><div class="review-lines"><div><span>Native balance</span><b>{{ balance??'—' }} SOL</b></div><div><span>{{ TOKEN_SYMBOL }} balance</span><b>{{ tokenConfigured?(tokenBalance??'—'):'Mint pending' }}</b></div></div><button class="button button-secondary full-width" :disabled="isRefreshing" @click="refreshBalances">{{ isRefreshing?'Refreshing...':'Refresh balance' }} <FlowIcon name="refresh"/></button><button class="text-button full-width" @click="disconnect">Disconnect wallet</button></template><button v-else class="button button-primary full-width" :disabled="isConnecting" @click="connect">{{ isConnecting?'Waiting for wallet...':'Connect Solana wallet' }} <FlowIcon name="wallet"/></button><p v-if="walletError" class="form-error" role="alert">{{ walletError }}</p><p v-if="tokenError" class="form-error" role="alert">{{ tokenError }}</p><p v-if="tokenNotice" class="token-notice">{{ tokenNotice }}</p><div v-if="tokenConfigured" class="mint-pending is-live"><span class="eyebrow">TOKEN STATUS</span><strong>{{ TOKEN_SYMBOL }} configured on {{ CLUSTER_LABEL }}</strong><p>Classic SPL Token; 9 decimals; zero initial supply. Mint authority retained; freeze authority disabled.</p><a class="mint-explorer" :href="TOKEN_EXPLORER_URL" target="_blank" rel="noopener noreferrer">View mint on Explorer <FlowIcon name="arrow"/></a><code class="mint-address">{{ TOKEN_MINT }}</code></div></template><template v-else><div class="dialog-kicker"><span class="dialog-icon"><FlowIcon name="book"/></span><span>POOLUMI / QUICK START</span></div><h2 id="dialog-title">From route to preview.</h2><p class="dialog-lead">Use the desk to compare fixture routes, tune an allocation, and save a local position preview.</p><div class="guide-step"><span>01</span><div><h3>Choose a route</h3><p>Compare pair, APR, TVL, volume and fee examples in the route board.</p></div></div><div class="guide-step"><span>02</span><div><h3>Compose a position</h3><p>Set an illustrative split, enter an amount, and review before saving.</p></div></div><div class="guide-step"><span>03</span><div><h3>Connect when needed</h3><p>Wallet connection is only for reading balances from the configured RPC.</p></div></div><button class="button button-primary full-width" @click="goTo('Pools')">Open route board <FlowIcon name="arrow"/></button></template></div></dialog><div v-if="toast" class="toast" role="status"><FlowIcon name="check"/><span>{{ toast }}</span><button class="icon-button" aria-label="Dismiss notification" @click="toast='' "><FlowIcon name="close"/></button></div></div>
</template>
